let promotionRecords={},promotionLoadWarning='';
const promotionKey=()=>state.store+'_'+state.date;
const getPromotionPlans=()=>promotionRecords[promotionKey()]||[];
const safeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function loadPromotions(){try{const value=JSON.parse((globalThis.WorkspaceStorage || localStorage).getItem('fresh-order-promotions-v1')||'{}');if(!value||Array.isArray(value)||typeof value!=='object')throw Error();promotionRecords=value;}catch{promotionLoadWarning='저장한 행사 조건을 읽지 못했습니다. 다시 입력해주세요.';promotionRecords={};}}
function savePromotionPlans(plans){const next={...promotionRecords,[promotionKey()]:plans};try{(globalThis.WorkspaceStorage || localStorage).setItem('fresh-order-promotions-v1',JSON.stringify(next));}catch{throw Error('브라우저에 저장하지 못했습니다. 저장 공간과 설정을 확인해주세요.');}promotionRecords=next;state.overrides={};render();}
function renderPromotions(){
 const root=$('#promotionSection'),w=forecastWindow(),plans=getPromotionPlans(),pw=PROMO.windows[state.date];if(!w||!pw)return;
 const ref=pw.references.find(r=>r.store===state.store&&!r.error),name=id=>{const m=PROMO.menus.find(m=>m.menu_id===id);return m?`${m.menu_name} [${m.is_set?'세트':'단품'} / ${id}]`:id;};
 root.innerHTML=`<div class="order-plan-heading"><div><div class="eyebrow">PROMOTIONS</div><h2>행사·수요 조정</h2><p></p></div><span class="badge">${plans.length?plans.length+'건 적용 중':'추가 조건 없음'}</span></div>${promotionLoadWarning?`<p class="warning">${safeText(promotionLoadWarning)}</p>`:''}<div id="appliedPromotions">${plans.map((p,j)=>`<div class="applied-promo"><div><b>${safeText(p.name)}</b><p>${safeText(p.target_menu_ids.map(name).join(', '))} · ${p.start_date}–${p.end_date}<br>${p.offer.type==='none'?'일반 수요 변화':p.offer.value+(p.offer.type==='percent_off'?'%':'원')+' 할인'} · ${p.response.mode==='manual'?'사용자 가정 '+p.response.uplift_pct+'%':'과거 '+safeText(p.response.reference_promo_id)+' 참고 (행사 1건)'}</p><small>${safeText(p.response.reason||'과거 관측 수요 변화의 미래 전이 가정')}</small></div><button class="button secondary" data-remove-promo="${j}">해제</button></div>`).join('')}</div><details id="promotionEditor"><summary>행사 추가</summary><form id="promotionForm"><div class="promo-form-grid"><label>입력 종류<select id="promoKind"><option value="promotion">프로모션 · 할인 행사</option><option value="special">일반 특이사항 · 수요 변화</option></select></label><label>행사 이름 / 특이사항<input id="promoName" maxlength="100" required placeholder="예: 주말 치즈버거 세트 할인"></label><label>적용 매장<input readonly value="${safeText(DATA.stores.find(s=>s.store_id===state.store).store_name)}"></label><label>시작일<input id="promoStart" type="date" min="${w.dates[0]}" max="${w.dates[6]}" value="${w.dates[0]}" required></label><label>종료일<input id="promoEnd" type="date" min="${w.dates[0]}" max="${w.dates[6]}" value="${w.dates[6]}" required></label><label id="offerTypeField">할인 방식<select id="promoOffer"><option value="percent_off">정률 할인 (%)</option><option value="amount_off">정액 할인 (원)</option></select></label><label id="offerValueField">할인 크기<input id="promoValue" type="number" min="0.000001" step="any" required placeholder="예: 10"></label></div><fieldset class="promo-menus"><legend>대상 메뉴 · 세트와 단품을 구분해 선택하세요</legend>${PROMO.menus.map(m=>`<label><input type="checkbox" name="promoMenu" value="${m.menu_id}">${safeText(name(m.menu_id))}</label>`).join('')}</fieldset><div class="promo-form-grid"><label>예상 수요 반응<select id="promoMode"><option value="manual">수동 가정 입력</option><option value="historical_reference" ${ref?'':'disabled'}>같은 매장의 과거 행사 참고${ref?'':' (참고 가능한 행사 없음)'}</option></select></label><label id="upliftField">예상 수요 변화율 (%)<input id="promoUplift" type="number" min="-100" max="200" step="any" placeholder="예: 30 (0도 입력 가능)"></label></div><div id="promoReference" hidden>${ref?`<b>${safeText(ref.id)} · ${ref.period.join('–')} · 독립 행사 1건</b><p>${ref.menus.map(mid=>safeText(name(mid))+': '+n((ref.factors[mid].factor-1)*100,1)+'%').join('<br>')}</p><label><input id="acceptPromoReference" type="checkbox"> 과거 변화가 이번 행사에도 적용된다는 가정임을 확인합니다.</label><p>할인율의 인과효과가 아니며, 조건 차이와 다른 영향을 분리할 수 없습니다.</p>`:''}</div><label class="promo-reason">근거 / 점장 메모<textarea id="promoReason" maxlength="500" rows="2" placeholder="예: 주변 행사로 방문이 늘 것으로 보아 +30% 수요를 가정"></textarea></label><details class="input-help"><summary>입력 안내</summary><p>일반 특이사항은 수동 수요 변화율로 반영합니다. 메모는 설명용이며 AI가 자동 해석하지 않습니다. 할인율만으로 수요 증가율을 추정하지 않습니다. 이번 예측 7일 내 행사만 적용합니다. 1+1·쿠폰·구성 변경은 현재 지원하지 않습니다. 입력은 이 브라우저의 매장·기준일별로 저장됩니다.</p></details><p id="promoError" class="warning" role="alert" hidden></p><button type="submit" class="button secondary">미리보기</button><div id="promoPreview" hidden></div></form></details>`;
 $$('[data-remove-promo]').forEach(b=>b.onclick=()=>{try{savePromotionPlans(plans.filter((_,j)=>j!==+b.dataset.removePromo));toast('행사를 해제하고 다시 계산했습니다.');}catch(e){toast(e.message);}});
 $('#promoKind').onchange=()=>{const special=$('#promoKind').value==='special';$('#offerTypeField').hidden=special;$('#offerValueField').hidden=special;$('#promoValue').required=!special;$('#promoMode').value='manual';$('#promoMode').disabled=special;$('#promoMode').onchange();};
 $('#promoMode').onchange=()=>{const historical=$('#promoMode').value==='historical_reference';$('#upliftField').hidden=historical;$('#promoReference').hidden=!historical;$$('[name="promoMenu"]').forEach(c=>{c.disabled=historical;if(historical)c.checked=ref.menus.includes(c.value);});$('#promoPreview').hidden=true;};
 $('#promotionForm').oninput=()=>{$('#promoPreview').hidden=true;};
 $('#promotionForm').onsubmit=e=>{e.preventDefault();try{
 const historical=$('#promoMode').value==='historical_reference';const uplift=$('#promoUplift').value;
 if(!historical&&uplift.trim()==='')throw Error('예상 수요 변화율을 직접 입력해주세요.');
 const special=$('#promoKind').value==='special';const p={kind:special?'special':'promotion',promotion_id:'PLAN_'+Date.now(),name:$('#promoName').value.trim(),store_ids:[state.store],target_menu_ids:$$('[name="promoMenu"]:checked').map(c=>c.value),start_date:$('#promoStart').value,end_date:$('#promoEnd').value,offer:special?{type:'none',value:0}:{type:$('#promoOffer').value,value:Number($('#promoValue').value)},response:historical?{mode:'historical_reference',reference_promo_id:ref.id,accept_transfer_assumption:$('#acceptPromoReference').checked}:{mode:'manual',uplift_pct:Number(uplift),reason:$('#promoReason').value.trim()}};
 const next=[...plans,p],before=PromotionEngine.project(PROMO,state.date,state.store,w.dates,plans),after=PromotionEngine.project(PROMO,state.date,state.store,w.dates,next);$('#promoError').hidden=true;
 $('#promoPreview').hidden=false;$('#promoPreview').innerHTML=`<h3>적용 전 미리보기</h3><p><b>${safeText(p.name)}</b> · ${p.start_date}–${p.end_date} · ${p.offer.type==='none'?'일반 수요 변화':p.offer.value+(p.offer.type==='percent_off'?'%':'원')+' 할인'}<br>${historical?'과거 행사 1건의 반응 전이 가정':'사용자 수요 가정 '+p.response.uplift_pct+'%'}</p><details><summary>메뉴별·날짜별 수요 확인</summary><div class="table-wrap"><table><thead><tr><th>메뉴</th><th>날짜</th><th>적용 전</th><th>적용 후</th></tr></thead><tbody>${p.target_menu_ids.flatMap(mid=>w.dates.map((d,k)=>`<tr><td>${safeText(name(mid))}</td><td>${d}</td><td>${n(before.menu[mid][k],1)}</td><td>${n(after.menu[mid][k],1)}</td></tr>`)).join('')}</tbody></table></div></details><div class="table-wrap"><table><thead><tr><th>식자재</th><th>7일 필요량 (전)</th><th>반영 후</th><th>차이</th></tr></thead><tbody>${activeSnapshot.filter(i=>Math.abs(after.ingredients[i.ingredient_id].reduce((a,b)=>a+b,0)-before.ingredients[i.ingredient_id].reduce((a,b)=>a+b,0))>1e-8).map(i=>{const beforeQty=before.ingredients[i.ingredient_id].reduce((a,b)=>a+b,0),afterQty=after.ingredients[i.ingredient_id].reduce((a,b)=>a+b,0);return `<tr><td>${safeText(i.ingredient_name)}</td><td>${qty(beforeQty,i)}</td><td>${qty(afterQty,i)}</td><td>${qty(afterQty-beforeQty,i)}</td></tr>`}).join('')||'<tr><td colspan="4">필요량 변화가 없습니다.</td></tr>'}</tbody></table></div><details class="input-help"><summary>입력 안내</summary><p>비대상 메뉴의 파급 효과와 행사 종료 후 잔효과는 포함하지 않습니다. 적용 시 수동 발주 수정은 초기화됩니다.</p></details><button type="button" id="applyPromotion" class="button primary">조건 적용</button>`;
 $('#applyPromotion').onclick=()=>{try{savePromotionPlans(next);toast('특이사항을 반영해 수요와 발주안을 다시 계산했습니다.');}catch(err){toast(err.message);}};
 }catch(err){$('#promoError').hidden=false;$('#promoError').textContent=err.message;$('#promoPreview').hidden=true;}};
}
